package agent
import("context";"log";"net/http";"sync";"time")
type Agent struct{cfg Config;log *log.Logger;packets *packetCapture;detector *detector;api *api;collector *collector;prev map[string]ifaceSample;test *testOverride;testWasActive bool;attackMu sync.Mutex;attackActive bool}
func New(c Config,l *log.Logger)(*Agent,error){return &Agent{cfg:c,log:l,packets:newPacketCapture(),detector:newDetector(c.Window),api:newAPI(),collector:newCollector(c),prev:map[string]ifaceSample{},test:newTestOverride()},nil}
func(a *Agent)Run(ctx context.Context)error{go a.packets.start(a.log);mux:=http.NewServeMux();a.api.routes(mux);a.registerTestRoutes(mux);server:=&http.Server{Addr:a.cfg.ListenAddr,Handler:securityHeaders(mux,a.cfg),ReadHeaderTimeout:3*time.Second};go func(){a.log.Printf("API listening on %s",a.cfg.ListenAddr);if e:=server.ListenAndServe();e!=nil&&e!=http.ErrServerClosed{a.log.Printf("API: %v",e)}}();ticker:=time.NewTicker(a.cfg.SampleInterval);defer ticker.Stop();for{select{case<-ctx.Done():sctx,cancel:=context.WithTimeout(context.Background(),3*time.Second);defer cancel();return server.Shutdown(sctx);case<-ticker.C:a.tick(ctx)}}}
func(a *Agent)tick(ctx context.Context){now:=time.Now();ifs,next:=interfaceStats(a.prev);a.prev=next;n,testMode:=a.packets.stats(),false;if synthetic,ok:=a.test.current(now);ok{n,testMode=synthetic,true}else if a.testWasActive{a.detector.reset()};a.testWasActive=testMode;names:=make([]string,0,len(ifs));for _,i:=range ifs{names=append(names,i.Name)};ev,hit:=a.detector.evaluate(now,n,a.cfg,names,a.cfg.HostID);ev.Test=testMode;if testMode&&hit{ev.Reason="TEST: "+ev.Reason};a.attackMu.Lock();previous:=a.attackActive;a.attackActive=hit;a.attackMu.Unlock();s:=Snapshot{Time:now.UTC(),HostID:a.cfg.HostID,Attack:hit,TestMode:testMode,System:systemStats(),Interfaces:ifs,Network:n};a.api.update(s,func()*AttackEvent{if hit{return &ev};return nil}());if hit&&!previous{suffix:="";if testMode{suffix=" (TEST)"};a.log.Printf("ATTACK DETECTED%s: %s",suffix,ev.Reason);a.collector.send(ctx,"/api/v1/events",ev)};a.collector.send(ctx,"/api/v1/telemetry",s)}
func securityHeaders(next http.Handler,cfg Config)http.Handler{return http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){w.Header().Set("X-Content-Type-Options","nosniff");w.Header().Set("Cache-Control","no-store");if cfg.CORSOrigin!=""{w.Header().Set("Access-Control-Allow-Origin",cfg.CORSOrigin);w.Header().Set("Access-Control-Allow-Headers","Authorization, Content-Type");w.Header().Set("Access-Control-Allow-Methods","GET, OPTIONS, POST")};if r.Method=="OPTIONS"{w.WriteHeader(http.StatusNoContent);return};if cfg.APIAuthToken!=""&&r.Header.Get("Authorization")!="Bearer "+cfg.APIAuthToken{http.Error(w,"unauthorized",http.StatusUnauthorized);return};next.ServeHTTP(w,r)})}
